    ll *prefix = (ll *)malloc(sizeof(ll) * (N + 1));
    prefix[0] = 0;
    for (int i = 0; i < N; i++) prefix[i + 1] = prefix[i] + A[i];

    // Count pairs (i, j) with A[i] + A[j] >= x
    ll low = 0, high = 200000 + 1; // Ai <= 1e5 in original constraints
    while (high - low > 1) {
        ll mid = (low + high) / 2;
        ll cnt = 0;
        int j = N - 1;
        for (int i = 0; i < N; i++) {
            while (j >= 0 && A[i] + A[j] < mid) j--;
            cnt += (j + 1);
        }
        if (cnt >= M) low = mid;
        else high = mid;
    }

    ll threshold = low;

    ll count = 0;
    ll sum = 0;
    int j = N - 1;
    for (int i = 0; i < N; i++) {
