using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    int64 M;
    cin >> N >> M;

    vector<int64> A(N);
    for (int i = 0; i < N; ++i) cin >> A[i];

    sort(A.begin(), A.end());

    // Prefix sums
    vector<int64> pref(N + 1, 0);
    for (int i = 0; i < N; ++i) pref[i + 1] = pref[i] + A[i];

    // Count pairs (i, j) with A[i] + A[j] >= x
    auto count_pairs = [&](int64 x) -> int64 {
        int64 cnt = 0;
        for (int i = 0; i < N; ++i) {
            int pos = lower_bound(A.begin(), A.end(), x - A[i]) - A.begin();
            cnt += (N - pos);
        }
        return cnt;
    };

    // Binary search maximum threshold T such that
    // number of pairs with sum >= T is at least M.
    int64 low = 0, high = 200000 + 200000 + 1; // [low, high)
    while (high - low > 1) {
        int64 mid = (low + high) / 2;
        if (count_pairs(mid) >= M) low = mid;
        else high = mid;
    }
    int64 T = low;

    // Sum of all pair sums >= T
    int64 total_cnt = 0;
    int64 total_sum = 0;
    for (int i = 0; i < N; ++i) {
        int pos = lower_bound(A.begin(), A.end(), T - A[i]) - A.begin();
        int64 c = N - pos;
        total_cnt += c;
        total_sum += c * A[i] + (pref[N] - pref[pos]);
    }

    // If we counted more than M pairs, subtract extra pairs of value exactly T
    total_sum -= (total_cnt - M) * T;

    cout << total_sum << '\n';
    return 0;
}

