public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        long M = Long.parseLong(st.nextToken());

        long[] A = new long[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            A[i] = Long.parseLong(st.nextToken());
        }

        Arrays.sort(A);

        // Prefix sums for fast range sum calculation
        long[] prefix = new long[N + 1];
        for (int i = 0; i < N; i++) {
            prefix[i + 1] = prefix[i] + A[i];
        }

        // Binary search to find the minimum sum value such that
        // number of pairs with sum >= that value is at least M
        long low = A[0] + A[0];  // minimum possible sum
        long high = A[N-1] + A[N-1];  // maximum possible sum
        long threshold = low;

        while (low <= high) {
            long mid = (low + high) / 2;
            long count = countPairsWithSumAtLeast(A, mid);
            if (count >= M) {
                threshold = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        // Count pairs with sum > threshold and sum >= threshold
        long countGreater = countPairsWithSumAtLeast(A, threshold + 1);
        long countThreshold = countPairsWithSumAtLeast(A, threshold) - countGreater;

        // Sum of all pairs with sum > threshold
        long sumGreater = sumPairsWithSumAtLeast(A, prefix, threshold + 1);

        // Need to add some pairs with sum == threshold to reach exactly M
        long needed = M - countGreater;
        long totalHappiness = sumGreater + needed * threshold;

        System.out.println(totalHappiness);
    }

    // Count number of pairs (i,j) with i < j such that A[i] + A[j] >= value
    static long countPairsWithSumAtLeast(long[] A, long value) {
        int N = A.length;
        long count = 0;
        int left = 0;
        int right = N - 1;
        while (left < right) {
            if (A[left] + A[right] >= value) {
                count += (right - left);
                right--;
            } else {
                left++;
            }
        }
        return count;
    }

    // Sum of all pairs (i,j) with i < j such that A[i] + A[j] >= value
    static long sumPairsWithSumAtLeast(long[] A, long[] prefix, long value) {
        int N = A.length;
        long sum = 0;
        int right = N - 1;
        for (int left = 0; left < N; left++) {
            // Find smallest right such that A[left] + A[right] >= value
            while (right > left && A[left] + A[right] >= value) {
                right--;
            }
            // Now right is the last index that doesn't satisfy, so valid are from right+1 to N-1
            int validStart = Math.max(right + 1, left + 1);
            if (validStart < N) {
                int cnt = N - validStart;
                sum += A[left] * cnt + (prefix[N] - prefix[validStart]);
            }
        }
        return sum;
    }
}

