        int total = N + 1;
        PriorityQueue<long[]> pq = new PriorityQueue<>((a,b) -> Long.compare(b[0], a[0]));
        Set<Long> visited = new HashSet<>();
        pq.offer(new long[]{A[0]+A[1], 0, 1});
        visited.add(0L * total + 1);
        long ans = 0;
        for (long k = 0; k < M; k++) {
            long[] cur = pq.poll();
            ans += cur[0];
            int i = (int)cur[1], j = (int)cur[2];
            if (j+1 < total && visited.add((long)i*total+(j+1))) pq.offer(new long[]{A[i]+A[j+1], i, j+1});
            if (i+1 < j && visited.add((long)(i+1)*total+j)) pq.offer(new long[]{A[i+1]+A[j], i+1, j});
        }
        System.out.println(ans);
    }
