import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        long M = fs.nextLong();
        long[] A = new long[N];
        for (int i = 0; i < N; i++) A[i] = fs.nextLong();

        Arrays.sort(A);

        long[] prefix = new long[N + 1];
        for (int i = 0; i < N; i++) prefix[i + 1] = prefix[i] + A[i];

        long low = 0;
        long high = 200000L + 1; // Ai <= 1e5 in original constraints, so sum <= 2e5

        while (high - low > 1) {
            long mid = (low + high) >>> 1;
            if (countPairsAtLeast(A, mid) >= M) {
                low = mid;
            } else {
                high = mid;
            }
        }

        long threshold = low;
        long count = 0;
        long sum = 0;

        for (int i = 0; i < N; i++) {
            int idx = lowerBound(A, threshold - A[i]);
            long c = N - idx;
            count += c;
            sum += A[i] * c + (prefix[N] - prefix[idx]);
        }

        // Remove excess pairs whose sum is exactly threshold
        sum -= (count - M) * threshold;

        System.out.println(sum);
    }

    static long countPairsAtLeast(long[] A, long x) {
        int N = A.length;
        long count = 0;
        for (int i = 0; i < N; i++) {
            int idx = lowerBound(A, x - A[i]);
            count += N - idx;
        }
        return count;
    }

    static int lowerBound(long[] a, long key) {
        int l = 0, r = a.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (a[m] >= key) r = m;
            else l = m + 1;
        }
        return l;
    }
